def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces in the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify the start and end indices of each group of nested parentheses
    groups = []
    start = 0
    stack = []
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            start = stack.pop()
            groups.append(paren_string[start:i+1])

    # Step 3: Extract each group based on the start and end indices
    result = []
    for group in groups:
        result.append(group)

    # Step 4: Check if each group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    result = [group for group in result if is_balanced(group)]

    # Step 5: Return the separated groups in a list
    return result

